// --- Step 5: Handle Graceful Shutdown ---
sigCh := make(chan os.Signal, 1)
signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

// ⚠ The ctx.Done() arm is what makes every `cancel()` above real. Before
// 2026-08-26 this was a bare `<-sigCh`, so the listener goroutines'
// cancel-on-failure calls were dead code ... Exiting turns "quietly
// broken" into a restart loop somebody sees.
select {
case receivedSignal := <-sigCh:
	appLogger.Info("Shutdown signal received", zap.String("signal", receivedSignal.String()))
case <-ctx.Done():
	appLogger.Error("Shutting down: a listener failed (see the error logged by its goroutine)")
}

var deliveryRoutePrefixes = []string{"/c/", "/d/"}   // admin-router guard: /d/ REFUSED there today
var boxServablePrefixes  = []string{"/c/"}          // what the vhost actually proxies; add "/d/" in the SAME commit as its location block

func assertNoDeliveryRoutes(routes gin.RoutesInfo) error {
	for _, r := range routes {
		for _, prefix := range deliveryRoutePrefixes {
			if strings.HasPrefix(r.Path, prefix) {
				return fmt.Errorf("delivery route %s %s is mounted on the main admin router: ...", r.Method, r.Path)
			}
		}
		if i := strings.Index(r.Path, "/*"); i >= 0 {
			static := r.Path[:i+1]
			for _, prefix := range deliveryRoutePrefixes {
				if strings.HasPrefix(prefix, static) {
					return fmt.Errorf("wildcard route %s %s ... can capture delivery path %s by prefix dispatch", r.Method, r.Path, prefix)
				}
			}
		}
	}
	return nil
}

func assertRoutesAreBoxServable(routes gin.RoutesInfo) error {
	for _, r := range routes {
		ok := false
		for _, prefix := range boxServablePrefixes {
			if r.Path == prefix+":token" {
				ok = true
				break
			}
		}
		if !ok {
			return fmt.Errorf("delivery route %s %s is not servable through the box: ...", r.Method, r.Path)
		}
	}
	return nil
}

type deliveryRouteRegistrar interface{ RegisterRoutes(gin.IRouter) }

func newDeliveryEngine(h deliveryRouteRegistrar) (*gin.Engine, error) {
	r := gin.New()
	r.Use(gin.Recovery())
	h.RegisterRoutes(r)
	if err := assertRoutesAreBoxServable(r.Routes()); err != nil {
		return nil, err
	}
	return r, nil
}

func newDeliveryServer(port string, h deliveryRouteRegistrar) (*http.Server, error) {
	if port == "" {
		return nil, nil
	}
	engine, err := newDeliveryEngine(h)
	if err != nil {
		return nil, err
	}
	return &http.Server{Addr: ":" + port, Handler: engine}, nil
}

